def _guardar_colores_originales(widget):
    # Guardo una sola vez los colores con los que fue creado cada widget.
    # Así puedo volver exactamente al modo claro al apretar nuevamente la luna.
    if hasattr(widget, "_sanca_colores_originales"):
        return
    colores = {}
    propiedades = (
        "bg", "fg", "activebackground", "activeforeground",
        "insertbackground", "selectbackground", "selectforeground",
        "highlightbackground", "troughcolor"
    )
    for propiedad in propiedades:
        try:
            colores[propiedad] = widget.cget(propiedad)
        except (tk.TclError, TypeError):
            # Algunos controles no tienen todas las opciones de color.
            continue
    widget._sanca_colores_originales = colores


def aplicar_tema(widget=None):
    # Si no recibo una ventana específica, aplico el tema desde la principal.
    if widget is None:
        widget = ventana
    _guardar_colores_originales(widget)
    colores_originales = widget._sanca_colores_originales
    clase = widget.winfo_class()

    if MODO_OSCURO:
        fondo_original = str(colores_originales.get("bg", "")).lower()
        texto_original = str(colores_originales.get("fg", "")).lower()

        # Conservo los colores institucionales, pero en una versión oscura.
        if fondo_original in (COLOR_NAVBAR.lower(), GRIS_AZULADO.lower(), AZUL_PETROLEO.lower()):
            fondo_widget = PANEL_AZUL_OSCURO
        elif fondo_original in (VERDE_AZULADO.lower(), COLOR_BOTON.lower()):
            fondo_widget = "#285D66"
        elif fondo_original in (COLOR_ERROR.lower(), ROJO.lower()):
            fondo_widget = "#873A3A"
        elif fondo_original in (COLOR_ACENTO.lower(), AMARILLO.lower()):
            fondo_widget = "#8A642B"
        else:
            fondo_widget = PANEL_OSCURO

        if clase in ("Tk", "Toplevel"):
            widget.configure(bg=FONDO_OSCURO)
        elif clase == "Frame":
            widget.configure(bg=FONDO_OSCURO if widget is ventana else fondo_widget)
        elif clase == "Label":
            color_texto = TEXTO_SECUNDARIO_OSCURO if texto_original in (GRIS_MEDIO.lower(), COLOR_LABEL.lower()) else TEXTO_OSCURO
            widget.configure(bg=fondo_widget, fg=color_texto)
        elif clase == "Button":
            if fondo_original in (COLOR_ERROR.lower(), ROJO.lower()):
                widget.configure(bg="#873A3A", fg=TEXTO_OSCURO, activebackground="#A94A4A", activeforeground=TEXTO_OSCURO)
            elif fondo_original in (COLOR_ACENTO.lower(), AMARILLO.lower()):
                widget.configure(bg="#A97930", fg="#171D27", activebackground="#C58B35", activeforeground="#171D27")
            elif fondo_original in (VERDE_AZULADO.lower(), COLOR_BOTON.lower(), COLOR_NAVBAR.lower()):
                widget.configure(bg="#285D78", fg=TEXTO_OSCURO, activebackground="#347694", activeforeground=TEXTO_OSCURO)
            else:
                widget.configure(bg=PANEL_OSCURO, fg=TEXTO_OSCURO, activebackground=SELECCION_OSCURA, activeforeground=TEXTO_OSCURO)
        elif clase == "Entry":
            widget.configure(bg=ENTRADA_OSCURA, fg=TEXTO_OSCURO, insertbackground=TEXTO_OSCURO,
                             selectbackground=SELECCION_OSCURA, selectforeground=TEXTO_OSCURO)
        elif clase == "Listbox":
            widget.configure(bg=ENTRADA_OSCURA, fg=TEXTO_OSCURO, selectbackground=SELECCION_OSCURA,
                             selectforeground=TEXTO_OSCURO, highlightbackground=PANEL_OSCURO)
        elif clase == "Text":
            widget.configure(bg=ENTRADA_OSCURA, fg=TEXTO_OSCURO, insertbackground=TEXTO_OSCURO,
                             selectbackground=SELECCION_OSCURA, selectforeground=TEXTO_OSCURO)
        elif clase == "Scrollbar":
            widget.configure(bg=PANEL_OSCURO, troughcolor=FONDO_OSCURO, activebackground=SELECCION_OSCURA)
        else:
            # Restauro exactamente los colores originales del diseño SANCA.
            try:
                if colores_originales:
                    widget.configure(**colores_originales)
            except tk.TclError:
                pass
    else:
        # Restauro exactamente los colores originales del diseño SANCA.
        try:
            if colores_originales:
                widget.configure(**colores_originales)
        except tk.TclError:
            pass

    # Recorro los elementos que están dentro del widget (Frames, Labels, botones, etc.).
    try:
        for hijo in widget.winfo_children():
            aplicar_tema(hijo)
    except tk.TclError:
        pass


