# BLOQUE 14: FUNCIONES PARA LA PANTALLA PRINCIPAL
# ============================================================
def refrescar_lista():
    # Vacío la lista antes de volver a cargarla.
    lista_personas.delete(0, tk.END)
    # La columna correcta de la tabla se llama "nombres".
    cursor.execute("SELECT nombres, apellido, dni FROM personas ORDER BY apellido, nombres")
    for nombre, apellido, dni in cursor.fetchall():
        lista_personas.insert(tk.END, f"{apellido}, {nombre} — DNI {dni}")
    # Actualizo el contador.
    cursor.execute("SELECT COUNT(*) FROM personas")
    cantidad = cursor.fetchone()[0]
    contador_legajos.config(text=f"Legajos registrados: {cantidad}")


def mostrar_foto(dni):
    cursor.execute("SELECT foto FROM personas WHERE dni = ?", (dni,))
    fila = cursor.fetchone()
    if fila and fila[0]:
        try:
            img = Image.open(BytesIO(fila[0]))
            img.thumbnail((300, 300))
            fondo = Image.new("RGB", (300, 300), BLANCO)
            x = (300 - img.width) // 2
            y = (300 - img.height) // 2
            fondo.paste(img, (x, y))
            foto = ImageTk.PhotoImage(fondo)
            visor_foto.configure(image=foto, text="")
            visor_foto.image = foto
            return
        except Exception:
            pass
    visor_foto.configure(image="", text="👤\nSin foto")
    visor_foto.image = None


def grids_nom_ape():
    label_nombre.grid()
    entry_nombre.grid()
    label_apellido.grid()
    entry_apellido.grid()


def grids_dni():
    label_dni.grid()
    entry_dni.grid()


def grids_remove_nom_ape():
    entry_nombre.grid_remove()
    label_apellido.grid_remove()
    entry_apellido.grid_remove()


def grids_remove_dni():
    label_dni.grid_remove()
    entry_dni.grid_remove()


def al_seleccionar(event=None):
    # Muestro los campos del formulario.
    grids_nom_ape()
    grids_dni()
    # Compruebo que se haya seleccionado una persona.
    seleccion = lista_personas.curselection()
    if not seleccion:
        return
    # Extraigo el DNI del texto seleccionado.
    texto = lista_personas.get(seleccion[0])
    dni = texto.split("DNI ")[1].strip()
    cursor.execute("SELECT nombres, apellido, dni FROM personas WHERE dni = ?", (dni,))
    fila = cursor.fetchone()
    if not fila:
        return
    # Cargo el nombre.
    entry_nombre.delete(0, tk.END)
    entry_nombre.insert(0, fila[0])
    # Cargo el apellido.
    entry_apellido.delete(0, tk.END)
    entry_apellido.insert(0, fila[1])
    # Cargo el DNI.
    entry_dni.delete(0, tk.END)
    entry_dni.insert(0, fila[2])
    # Muestro la fotografía guardada.
    mostrar_foto(dni)


def limpiar():
    # Borro los campos de texto.
    entry_nombre.delete(0, tk.END)
    entry_apellido.delete(0, tk.END)
    entry_dni.delete(0, tk.END)
    # Restablezco el visor de fotografía.
    visor_foto.configure(image="", text="👤\nSin foto")
    visor_foto.image = None


def agregar_definitivo():
    # Obtengo los datos escritos por el usuario.
    nombre = entry_nombre.get().strip()
    apellido = entry_apellido.get().strip()
    dni_txt = entry_dni.get().strip()

    # Verifico que no falte ningún dato obligatorio.
    if not nombre or not apellido or not dni_txt:
        messagebox.showwarning("Faltan datos", "Completa nombre, apellido y DNI.")
        return

    # Compruebo que el DNI contenga solamente números.
    if not dni_txt.isdigit():
        messagebox.showerror("DNI inválido", "El DNI debe contener solamente números.")
        return

    dni = int(dni_txt)

    # Selecciono una fotografía. Cancelar permite guardar sin foto.
    ruta_foto = filedialog.askopenfilename(
        title="Seleccionar fotografía (opcional)",
        filetypes=[("Imágenes", "*.png *.jpg *.jpeg *.bmp *.webp"), ("Todos los archivos", "*.*")]
    )

    # Por defecto, la persona se guarda sin fotografía.
    foto = None

    # Si se eligió una imagen, compruebo que Pillow pueda abrirla.
    if ruta_foto:
        try:
            with Image.open(ruta_foto) as imagen:
                imagen.verify()
            # Leo el archivo en formato binario para guardarlo en SQLite.
            with open(ruta_foto, "rb") as archivo:
                foto = sqlite3.Binary(archivo.read())
        except Exception as error:
            messagebox.showerror(
                "Fotografía inválida",
                f"No se pudo abrir la imagen.\n\nDetalle: {error}"
            )
            return

    # Guardo la persona. La columna se llama "nombres", no "nombre".
    try:
        cursor.execute(
            "INSERT INTO personas (nombres, apellido, dni, foto) VALUES (?, ?, ?, ?)",
            (nombre, apellido, dni, foto)
        )
        conexion.commit()
        # También creo la carpeta del legajo.
        ruta_carpeta_legajo(dni)
    except sqlite3.IntegrityError:
        messagebox.showerror("DNI duplicado", "Ya existe una persona con ese DNI.")
        return
    except sqlite3.Error as error:
        conexion.rollback()
        messagebox.showerror(
            "Error al guardar",
            f"No se pudo guardar la persona.\n\nDetalle: {error}"
        )
        return

    # Actualizo la lista, limpio el formulario y aviso que terminó.
    refrescar_lista()
    limpiar()
    messagebox.showinfo("Persona agregada", "La persona se guardó correctamente.")


def eliminar_definitivo():
    seleccion = lista_personas.curselection()
    if not seleccion:
        messagebox.showwarning("Atencion", "Selecciona una persona de la lista para eliminar.")
        return

    texto = lista_personas.get(seleccion[0])
    dni = int(texto.split("DNI ")[1])

    if not messagebox.askyesno("Confirmar eliminación", f"¿Estas seguro de que deseas eliminar a esta persona?\n{texto}"):
        return

    grids_remove_nom_ape()
    grids_remove_dni()

    try:
        cursor.execute("DELETE FROM pdf WHERE dni_personas = ?", (dni,))
        cursor.execute("DELETE FROM personas WHERE dni = ?", (dni,))
        conexion.commit()
        # Borro también la carpeta del legajo si existe.
        eliminar_carpeta_legajo(dni)
    except sqlite3.Error as error:
        conexion.rollback()
        messagebox.showerror("Error al eliminar", f"No se pudo eliminar:\n{error}")
        return

    refrescar_lista()
    visor_foto.configure(image="", text="👤\nSin foto")
    visor_foto.image = None
    messagebox.showinfo("OK", "Persona eliminada correctamente.")


def buscar_definitivo():
    dni_txt = entry_dni.get().strip()
    nombre_buscar = entry_nombre.get().strip()
    apellido_buscar = entry_apellido.get().strip()

    if not dni_txt or not nombre_buscar or not apellido_buscar:
        messagebox.showwarning("Atencion", "Escribi los datos correctamente para buscar.")
        return

    cursor.execute(
        "SELECT nombres, apellido, dni FROM personas WHERE nombres = ? AND apellido = ? AND dni = ?",
        (nombre_buscar, apellido_buscar, dni_txt,)
    )
    fila = cursor.fetchone()

    if not fila:
        messagebox.showinfo("Sin resultados", "No existe esa persona.")
        return

    grids_nom_ape()
    entry_nombre.delete(0, tk.END)
    entry_nombre.insert(0, fila[0])
    entry_apellido.delete(0, tk.END)
    entry_apellido.insert(0, fila[1])
    mostrar_foto(fila[2])

    for i in range(lista_personas.size()):
        if f"DNI {fila[2]}" in lista_personas.get(i):
            lista_personas.selection_clear(0, tk.END)
            lista_personas.selection_set(i)
            lista_personas.see(i)
            break


