    Label(frame_izquierdo, text=" Apellido:", bg=COLOR_FONDO, fg=GRIS_AZULADO, font=("Segoe UI", 12)).grid(row=fila, column=0, sticky="e", padx=5)
    entry_apellido_perfil = Entry(frame_izquierdo, width=22, font=("Segoe UI", 12))
    entry_apellido_perfil.grid(row=fila, column=1, padx=5, pady=3)
    entry_apellido_perfil.insert(0, entry_apellido.get())
    fila += 1

    Label(frame_izquierdo, text="Edad:", bg=COLOR_FONDO, fg=GRIS_AZULADO, font=("Segoe UI", 12)).grid(row=fila, column=0, sticky="e", padx=5)
    entry_edad_perfil = Entry(frame_izquierdo, width=22, font=("Segoe UI", 12))
