    def mostrar_foto_en_perfil():
        dni_txt = entry_dni_perfil.get().strip()
        if dni_txt:
            cursor.execute("SELECT nombre FROM pdf WHERE dni_personas = ? ORDER BY id", (dni_txt,))
            filas = cursor.fetchall()
            if lista_fotos_galeria.size() != len(filas):
                lista_fotos_galeria.delete(0, tk.END)
                for (nombre,) in filas:
                    lista_fotos_galeria.insert(tk.END, nombre)

        if foto_pendiente["bytes"] == b"":
            visor_foto_perfil.configure(image="", text="👤\nClic para subir foto")
            visor_foto_perfil.image = None
            return

        if foto_pendiente["bytes"] is not None:
            try:
                img = Image.open(BytesIO(foto_pendiente["bytes"]))
                img.thumbnail((300, 300))
                foto_tk = ImageTk.PhotoImage(img)
                visor_foto_perfil.configure(image=foto_tk, text="")
                visor_foto_perfil.image = foto_tk
                return
            except Exception:
                pass

        dni_txt = entry_dni_perfil.get().strip()
        if not dni_txt:
            visor_foto_perfil.configure(image="", text="👤\nClic para subir foto")
            visor_foto_perfil.image = None
            return

        cursor.execute("SELECT foto FROM personas WHERE dni = ?", (dni_txt,))
        fila = cursor.fetchone()
        if fila and fila[0]:
            try:
                img = Image.open(BytesIO(fila[0]))
                img.thumbnail((300, 300))
                foto = ImageTk.PhotoImage(img)
                visor_foto_perfil.configure(image=foto, text="")
                visor_foto_perfil.image = foto
                return
            except Exception:
                pass

        visor_foto_perfil.configure(image="", text="👤\nClic para subir foto")
        visor_foto_perfil.image = None

    def subir_foto_perfil(event=None):
        ruta = filedialog.askopenfilename(
            title="Seleccionar foto",
            filetypes=[("Imagenes", "*.png *.jpg *.jpeg *.bmp *.webp")]
        )
        if not ruta:
            return
        try:
            with open(ruta, "rb") as f:
                foto_pendiente["bytes"] = f.read()
            mostrar_foto_en_perfil()
        except Exception as error:
            messagebox.showerror("Error", f"No se pudo cargar la foto: {error}")
            foto_pendiente["bytes"] = None
            return

    def asignar_foto_galeria(event=None):
        sel = lista_fotos_galeria.curselection()
        if not sel:
            return
        dni_txt = entry_dni_perfil.get().strip()
        if not dni_txt:
            return
        cursor.execute("SELECT contenido FROM pdf WHERE dni_personas = ? ORDER BY id", (dni_txt,))
        filas = cursor.fetchall()
        if sel[0] >= len(filas):
            return
        foto_pendiente["bytes"] = filas[sel[0]][0]
        mostrar_foto_en_perfil()

    def quitar_foto_perfil():
        foto_pendiente["bytes"] = b""
        mostrar_foto_en_perfil()

    def guardar_cambios_perfil():
        # Leo y valido los datos principales.
        nombre = entry_nombre_perfil.get().strip()
        apellido = entry_apellido_perfil.get().strip()
        dni_txt = entry_dni_perfil.get().strip()

        if not nombre or not apellido or not dni_txt:
            messagebox.showwarning("Faltan datos", "Completa nombre, apellido y DNI.")
            return

        if not dni_txt.isdigit():
            messagebox.showerror("DNI inválido", "El DNI debe contener solamente números.")
            return

        dni = int(dni_txt)

        # Leo los demás campos del perfil.
        edad_txt = entry_edad_perfil.get().strip()
        edad = int(edad_txt) if edad_txt.isdigit() else None
        domicilio = entry_direccion_perfil.get().strip()
        fecha_nacimiento = entry_f_nacimiento_perfil.get().strip()
        fecha_ingreso = entry_fecha_ingreso_perfil.get().strip()
        telefono = entry_telefono_perfil.get().strip()
        contacto_emergencia = entry_contacto_emergencia_perfil.get().strip()
        telefono_emergencia = entry_tel_emergencia_perfil.get().strip()
        obra_social = entry_obra_social_perfil.get().strip()
        nacionalidad = entry_nacionalidad.get().strip()
        localidad = entry_localidad.get().strip()
        mail = entry_mail_perfil.get().strip()
        cursos_hechos = entry_cursos_hechos_perfil.get().strip()
        cursos_en_progreso = entry_cursos_progreso_perfil.get().strip()

        foto = foto_pendiente["bytes"]
        dni_anterior = dni_original["valor"]

        try:
            if dni_anterior:
                # Compruebo que el DNI nuevo no pertenezca a otra persona.
                cursor.execute(
                    "SELECT dni FROM personas WHERE dni = ? AND dni <> ?",
                    (dni, dni_anterior)
                )
                if cursor.fetchone():
                    messagebox.showerror("DNI duplicado", "Otra persona ya utiliza ese DNI.")
                    return

                # Actualizo todos los campos del registro existente.
                cursor.execute("""UPDATE personas
                    SET nombres = ?, apellido = ?, dni = ?, edad = ?, domicilio = ?,
                        fecha_nacimiento = ?, fecha_ingreso = ?, telefono = ?, mail = ?,
                        contacto_emergencia = ?, telefono_emergencia = ?, obra_social = ?,
                        localidad = ?, nacionalidad = ?, cursos_hechos = ?, cursos_en_progreso = ?
                    WHERE dni = ?""", (
                    nombre, apellido, dni, edad, domicilio,
                    fecha_nacimiento, fecha_ingreso, telefono, mail,
                    contacto_emergencia, telefono_emergencia, obra_social,
                    localidad, nacionalidad, cursos_hechos, cursos_en_progreso,
                    dni_anterior
                ))

                # Muevo la carpeta del legajo si cambió el DNI.
                if str(dni) != str(dni_anterior):
                    mover_carpeta_legajo(dni_anterior, dni)

                # Actualizo la fotografía solamente si se hizo un cambio.
                if foto == b"":
                    cursor.execute("UPDATE personas SET foto = NULL WHERE dni = ?", (dni,))
                elif foto is not None:
                    cursor.execute("UPDATE personas SET foto = ? WHERE dni = ?", (sqlite3.Binary(foto), dni))
            else:
                # Si el perfil todavía no pertenece a una persona, creo el registro.
                cursor.execute("""INSERT INTO personas (
                    nombres, apellido, dni, edad, domicilio, fecha_nacimiento,
                    fecha_ingreso, telefono, mail, contacto_emergencia,
                    telefono_emergencia, obra_social, localidad, nacionalidad,
                    cursos_hechos, cursos_en_progreso, foto
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""", (
                    nombre, apellido, dni, edad, domicilio, fecha_nacimiento,
                    fecha_ingreso, telefono, mail, contacto_emergencia,
                    telefono_emergencia, obra_social, localidad, nacionalidad,
                    cursos_hechos, cursos_en_progreso,
                    sqlite3.Binary(foto) if foto else None
                ))
                ruta_carpeta_legajo(dni)

            conexion.commit()
        except sqlite3.IntegrityError:
            conexion.rollback()
            messagebox.showerror("DNI duplicado", "Ya existe una persona con ese DNI.")
            return
        except sqlite3.Error as error:
            conexion.rollback()
            messagebox.showerror("Error al guardar", f"No se pudieron guardar los datos:\n{error}")
            return

        # Actualizo el DNI original y la lista principal.
        dni_original["valor"] = str(dni)
        entry_dni_perfil.delete(0, tk.END)
        entry_dni_perfil.insert(0, str(dni))
        entry_dni.delete(0, tk.END)
        entry_dni.insert(0, str(dni))

        refrescar_lista()
        foto_pendiente["bytes"] = None
        mostrar_foto_en_perfil()
        mostrar_foto(dni)
        messagebox.showinfo("Datos guardados", "Los datos de la persona se guardaron correctamente.")

    def cargar_perfil():
        dni_txt = entry_dni.get().strip()
        lista_personas_perfil.delete(0, tk.END)
        foto_pendiente["bytes"] = None

        cursor.execute("""SELECT
                nombres, apellido, edad, domicilio, fecha_nacimiento,
                fecha_ingreso, telefono, contacto_emergencia, telefono_emergencia,
                obra_social, localidad, nacionalidad, cursos_hechos, cursos_en_progreso
            FROM personas WHERE dni = ?""", (dni_txt,))
        fila = cursor.fetchone()

        if fila:
            entry_nombre_perfil.delete(0, tk.END)
            entry_nombre_perfil.insert(0, fila[0] or "")
            entry_apellido_perfil.delete(0, tk.END)
            entry_apellido_perfil.insert(0, fila[1] or "")
            entry_edad_perfil.delete(0, tk.END)
            entry_edad_perfil.insert(0, fila[2] or "")
            entry_direccion_perfil.delete(0, tk.END)
            entry_direccion_perfil.insert(0, fila[3] or "")
            entry_f_nacimiento_perfil.delete(0, tk.END)
            entry_f_nacimiento_perfil.insert(0, fila[4] or "")
            entry_fecha_ingreso_perfil.delete(0, tk.END)
            entry_fecha_ingreso_perfil.insert(0, fila[5] or "")
            entry_telefono_perfil.delete(0, tk.END)
            entry_telefono_perfil.insert(0, fila[6] or "")
            entry_contacto_emergencia_perfil.delete(0, tk.END)
            entry_contacto_emergencia_perfil.insert(0, fila[7] or "")
            entry_tel_emergencia_perfil.delete(0, tk.END)
            entry_tel_emergencia_perfil.insert(0, fila[8] or "")
            entry_obra_social_perfil.delete(0, tk.END)
            entry_obra_social_perfil.insert(0, fila[9] or "")
            entry_localidad.delete(0, tk.END)
            entry_localidad.insert(0, fila[10] or "")
            entry_nacionalidad.delete(0, tk.END)
            entry_nacionalidad.insert(0, fila[11] or "")
            entry_cursos_hechos_perfil.delete(0, tk.END)
            entry_cursos_hechos_perfil.insert(0, fila[12] or "")
            entry_cursos_progreso_perfil.delete(0, tk.END)
            entry_cursos_progreso_perfil.insert(0, fila[13] or "")

            dni_original["valor"] = dni_txt

            try:
                cursor.execute("""SELECT id, nombres, apellido, dni
                    FROM personas WHERE dni = ? ORDER BY id""", (dni_txt,))
                for e in cursor.fetchall():
                    lista_personas_perfil.insert(tk.END, f"Estudiante {e[0]} — {e[2]} {e[1] or ''}")
            except sqlite3.Error:
                lista_personas_perfil.insert(tk.END, "Todavía no hay alumnos registrados.")

            mostrar_foto_en_perfil()
        else:
            messagebox.showinfo("Error", "No existe ese DNI.")

    def _texto_ficha_persona():
        """Construye el texto de la ficha usando las columnas reales de personas."""
        dni_txt = entry_dni_perfil.get().strip()
        if not dni_txt:
            messagebox.showwarning("Atención", "No hay una persona seleccionada.")
            return None

        cursor.execute("""SELECT
                nombres, apellido, dni, edad, domicilio, fecha_ingreso,
                telefono, mail, fecha_nacimiento, contacto_emergencia, telefono_emergencia,
                obra_social, nacionalidad, localidad, cursos_hechos, cursos_en_progreso
            FROM personas WHERE dni = ?""", (dni_txt,))
        p = cursor.fetchone()

        if not p:
            messagebox.showinfo("Sin resultados", "No existe ese DNI.")
            return None

        nombre_completo = f"{p[0] or ''} {p[1] or ''}".strip()

        lineas = [
            f"## {nombre_completo}",
            f"DNI: {p[2] or '-'}  |  Edad: {p[3] or '-'}",
            "",
            "# DATOS PERSONALES",
            f"Nombre: {p[0] or '-'}",
            f"Apellido: {p[1] or '-'}",
            f"DNI: {p[2] or '-'}",
            f"Edad: {p[3] or '-'}",
            f"Fecha de nacimiento: {p[8] or '-'}",
            f"Nacionalidad: {p[12] or '-'}",
            "",
            "# CONTACTO",
            f"Telefono: {p[6] or '-'}",
            f"Correo electrónico: {p[7] or '-'}",
            f"Domicilio: {p[4] or '-'}",
            f"Localidad: {p[13] or '-'}",
            f"Contacto de emergencia: {p[9] or '-'}",
            f"Telefono de emergencia: {p[10] or '-'}",
            "",
            "# SALUD",
            f"Obra social: {p[11] or '-'}",
            "",
            "# INSTITUTO",
            f"Fecha de ingreso al instituto: {p[5] or '-'}",
            f"Cursos hechos: {p[14] or '-'}",
            f"Cursos en progreso: {p[15] or '-'}",
            ""
        ]
        return "\n".join(lineas)

    def exportar_pdf_persona():
        texto = _texto_ficha_persona()
        if texto is None:
            return
        ruta = filedialog.asksaveasfilename(
            title="Guardar perfil como PDF",
            defaultextension=".pdf",
            initialfile=f"perfil_{entry_dni_perfil.get().strip()}.pdf",
            filetypes=[("PDF", "*.pdf")]
        )
        if not ruta:
            return
        dni = entry_dni_perfil.get().strip()
        cursor.execute("SELECT foto FROM personas WHERE dni = ?", (dni,))
        fila = cursor.fetchone()
        foto_bytes = fila[0] if fila and fila[0] else None
        try:
            crear_pdf_de_texto(ruta, texto, foto_bytes)
            messagebox.showinfo("OK", f"Perfil guardado en:\n{ruta}")
        except Exception:
            traceback.print_exc()
            messagebox.showerror("Error", "No se pudo crear el PDF.")

