def abrir_ventana_ver_documento(dni_persona=None):
    ventana_doc = Toplevel(ventana)
    ventana_doc.title("Ver / Editar documento")
    ventana_doc.geometry("900x750")
    ventana_doc.config(bg=GRIS_NIEBLA)

    frame_sup = Frame(ventana_doc, bg=GRIS_NIEBLA)
    frame_sup.pack(side="top", fill="x", padx=10, pady=10)

    Label(frame_sup, text="DNI del paciente:", bg=GRIS_NIEBLA, fg=GRIS_AZULADO, font=("Segoe UI", 12)).pack(side="left", padx=5)
    entry_dni_doc = Entry(frame_sup, width=20, font=("Segoe UI", 12))
    entry_dni_doc.pack(side="left", padx=5)
    if dni_persona:
        entry_dni_doc.insert(0, dni_persona)

    frame_texto = Frame(ventana_doc, bg=BLANCO, relief="solid", bd=1)
    frame_texto.pack(fill="both", expand=True, padx=10, pady=5)

    scroll_doc = tk.Scrollbar(frame_texto, orient="vertical")
    scroll_doc.pack(side="right", fill="y")

    text_doc = tk.Text(frame_texto, font=("Segoe UI", 11), wrap="word", yscrollcommand=scroll_doc.set, bg=BLANCO, fg=GRIS_AZULADO)
    text_doc.pack(side="left", fill="both", expand=True)
    scroll_doc.config(command=text_doc.yview)

    def cargar_documento():
        dni = entry_dni_doc.get().strip()
        text_doc.delete("1.0", tk.END)
        if not dni:
            messagebox.showwarning("Atención", "Escribí un DNI primero.")
            return
        cursor.execute("""SELECT
                id, nombres, apellido, dni, edad, domicilio, fecha_ingreso,
                telefono, mail, fecha_nacimiento, contacto_emergencia,
                telefono_emergencia, obra_social, nacionalidad, localidad
            FROM personas WHERE dni = ? ORDER BY id""", (dni,))
        filas = cursor.fetchall()
        if not filas:
            text_doc.insert("1.0", "No hay archivos para ese DNI.")
            return
        for f in filas:
            text_doc.insert(tk.END, f"=== Numero de ficha de alumno {f[0]} ===\n")
            text_doc.insert(tk.END, f"Nombre y apellido: {f[1]} {f[2] or ''}\n")
            text_doc.insert(tk.END, f"DNI: {f[3]} {f[4] or ''}\n")
            text_doc.insert(tk.END, f"{f[6] or ''}\n")

    def guardar_pdf():
        texto = text_doc.get("1.0", tk.END).strip()
        if not texto:
            messagebox.showwarning("Atención", "El documento está vacío.")
            return
        ruta = filedialog.asksaveasfilename(
            title="Guardar como PDF",
            defaultextension=".pdf",
            initialfile="documento.pdf",
            filetypes=[("PDF", "*.pdf")]
        )
        if not ruta:
            return
        try:
            crear_pdf_de_texto(ruta, texto)
            messagebox.showinfo("OK", f"PDF guardado en:\n{ruta}")
        except Exception:
            messagebox.showerror("Error", "No se pudo guardar el PDF.")

    def guardar_word():
        texto = text_doc.get("1.0", tk.END).strip()
        if not texto:
            messagebox.showwarning("Atención", "El documento está vacío.")
            return
        ruta = filedialog.asksaveasfilename(
            title="Guardar como Word",
            defaultextension=".rtf",
            initialfile="documento.rtf",
            filetypes=[("Word (RTF)", "*.rtf")]
        )
        if not ruta:
            return
        try:
            crear_word_de_texto(ruta, texto)
            messagebox.showinfo("OK", f"Word guardado en:\n{ruta}")
        except Exception:
            messagebox.showerror("Error", "No se pudo guardar el Word.")

    def eliminar_archivo():
        ruta = filedialog.askopenfilename(
            title="Elegir archivo a eliminar",
            filetypes=[("Documentos", "*.pdf *.doc *.docx *.txt")]
        )
        if not ruta:
            return
        if not messagebox.askyesno("Confirmar", f"¿Eliminar este archivo?\n{ruta}"):
            return
        try:
            os.remove(ruta)
            messagebox.showinfo("OK", "Archivo eliminado.")
        except Exception:
            messagebox.showerror("Error", "No se pudo eliminar el archivo.")

    def importar_documento():
        ruta = filedialog.askopenfilename(
            title="Importar documento",
            filetypes=[("Documentos", "*.pdf *.doc *.docx *.txt"), ("Todos", "*.*")]
        )
        if not ruta:
            return
        extension = os.path.splitext(ruta)[1].lower()
        texto = ""
        try:
            if extension == ".pdf":
                with open(ruta, "rb") as archivo:
                    lector = PyPDF2.PdfReader(archivo)
                    for pagina in lector.pages:
                        texto += (pagina.extract_text() or "") + "\n"
            elif extension == ".docx":
                with zipfile.ZipFile(ruta, "r") as documento:
                    contenido_xml = documento.read("word/document.xml").decode("utf-8")
                    contenido_xml = re.sub(r"</w:p>", "\n", contenido_xml)
                    texto = html.unescape(re.sub(r"<[^>]+>", "", contenido_xml))
            elif extension == ".txt":
                with open(ruta, "r", encoding="utf-8") as archivo:
                    texto = archivo.read()
            elif extension == ".doc":
                messagebox.showwarning("Formato no compatible", "El formato .doc antiguo no se puede leer directamente. Guardalo como .docx o PDF y volvé a importarlo.")
                return
            else:
                messagebox.showwarning("Formato", "Formato no soportado. Usá PDF, DOC, DOCX o TXT.")
                return
        except Exception:
            messagebox.showerror("Error al importar", "No se pudo leer el documento.")
            return

        text_doc.delete("1.0", tk.END)
        text_doc.insert("1.0", texto.strip() or "(El documento no tiene texto extraíble.)")
        messagebox.showinfo("Importado", f"Documento cargado:\n{ruta}")

    frame_btn_doc = Frame(ventana_doc, bg=GRIS_NIEBLA)
    frame_btn_doc.pack(anchor="center")

    Button(frame_btn_doc, bg=COLOR_BOTON, fg=COLOR_BOTON_TEXTO, text="⟳", command=cargar_documento).pack(side="left", padx=5)
    Button(frame_btn_doc, bg=COLOR_BOTON, fg=COLOR_BOTON_TEXTO, text="Guardar PDF", command=guardar_pdf).pack(side="left", padx=5)
    Button(frame_btn_doc, bg=COLOR_BOTON, fg=COLOR_BOTON_TEXTO, text="Guardar Word", command=guardar_word).pack(side="left", padx=5)
    Button(frame_btn_doc, bg=ROJO, fg=BLANCO, text="Eliminar archivo", command=eliminar_archivo).pack(side="left", padx=5)
    Button(frame_btn_doc, bg=COLOR_BOTON, fg=COLOR_BOTON_TEXTO, text="Importar PDF/Word", command=importar_documento).pack(side="left", padx=5)
    Button(frame_btn_doc, bg=COLOR_BOTON, fg=COLOR_BOTON_TEXTO, text="Autores", command=abrir_ventana_autores).pack(side="left", padx=5)

    if dni_persona:
        cargar_documento()

    aplicar_tema_ventana_nueva(ventana_doc)

# ============================================================
# BLOQUE 23: PDF Y WORD PARA CURSOS
# ============================================================
def crear_pdf_de_texto_cursos(ruta, texto):
    paginas = []
    lineas_pagina = []
    # Como no hay foto, el texto puede empezar más arriba
    y = 805

    def cerrar_pagina():
        nonlocal lineas_pagina, y
        if lineas_pagina:
            paginas.append(lineas_pagina)
        lineas_pagina = []
        y = 805

    for linea in texto.splitlines() or [""]:
        if y < 55:
            cerrar_pagina()
        if linea.startswith("## "):
            texto_linea = linea[3:]
            tamano = 24
            es_header = True
            espacio = 36
        elif linea.startswith("# "):
            texto_linea = linea[2:]
            tamano = 14
            es_header = True
            espacio = 24
        else:
            texto_linea = linea
            tamano = 10
            es_header = False
            espacio = 15
        lineas_pagina.append((texto_linea, y, es_header, tamano))
        y -= espacio

    cerrar_pagina()
    if not paginas:
        paginas = [[]]

    for n, lineas in enumerate(paginas, start=1):
        lineas.append((f"Pagina {n} de {len(paginas)}", 35, False, 10))

    objetos = [None, None]
    referencias = []
    id_fuente = 3 + 2 * len(paginas)
    id_fuente_bold = id_fuente + 1

    for idx, lineas in enumerate(paginas):
        def _fmt(linea, pos_y, es_header, tamano):
            fuente = "F2" if es_header else "F1"
            return f"BT /{fuente} {tamano} Tf 1 0 0 1 50 {pos_y} Tm <{linea.encode('cp1252', errors='replace').hex().upper()}> Tj ET\n"

        contenido_str = "".join(_fmt(linea, pos_y, es_header, tam) for linea, pos_y, es_header, tam in lineas)
        contenido = contenido_str.encode("ascii")

        id_pagina = len(objetos) + 1
        id_contenido = id_pagina + 1
        referencias.append(f"{id_pagina} 0 R")

        # Sin foto, solo necesitamos las fuentes
        recursos = f"/Resources << /Font << /F1 {id_fuente} 0 R /F2 {id_fuente_bold} 0 R >> >>"

        objetos.append(f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] {recursos} /Contents {id_contenido} 0 R >>".encode("ascii"))
        objetos.append(f"<< /Length {len(contenido)} >>\nstream\n".encode("ascii") + contenido + b"\nendstream")

    objetos[0] = b"<< /Type /Catalog /Pages 2 0 R >>"
    objetos[1] = f"<< /Type /Pages /Kids [{' '.join(referencias)}] /Count {len(referencias)} >>".encode("ascii")
    objetos.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
    objetos.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>")

    salida = bytearray(b"%PDF-1.4\n")
    offsets = [0]
    for numero, objeto in enumerate(objetos, start=1):
        offsets.append(len(salida))
        salida.extend(f"{numero} 0 obj\n".encode("ascii"))
        salida.extend(objeto)
        salida.extend(b"\nendobj\n")

    pos = len(salida)
    salida.extend(f"xref\n0 {len(objetos)+1}\n".encode("ascii"))
    salida.extend(b"0000000000 65535 f \n")
    for offset in offsets[1:]:
        salida.extend(f"{offset:010d} 00000 n \n".encode("ascii"))
    salida.extend(f"trailer\n<< /Size {len(objetos)+1} /Root 1 0 R >>\nstartxref\n{pos}\n%%EOF\n".encode("ascii"))

    with open(ruta, "wb") as archivo:
        archivo.write(salida)
def crear_word_de_texto_cursos(ruta, texto):
    def escapar_rtf(s):
        salida = []
        for ch in s:
            if ch == "\\":
                salida.append("\\\\")
            elif ch == "{":
                salida.append("\\{")
            elif ch == "}":
                salida.append("\\}")
            elif ord(ch) > 127:
                try:
                    val = ord(ch)
                    if val < 0:
                        val += 65536
                    if val < 32768:
                        salida.append(f"\\u{val}?")
                    else:
                        salida.append(f"\\u{val - 65536}?")
                except Exception:
                    salida.append(ch)
            else:
                salida.append(ch)
        return "".join(salida)

    partes = [
        "{\\rtf1\\ansi\\deff0",
        "{\\fonttbl{\\f0 Arial;}}",
        "{\\colortbl ;\\red0\\green0\\blue0;}",
        "\\paperw11906\\paperh16838\\margl1000\\margr1000\\margt1000\\margb1000",
        "\\viewkind4\\uc1\\pard\\cf1\\f0\\fs24\n"
    ]

    # Como no hay foto, el texto ocupa toda la página sin tabla
    for linea in (texto.splitlines() or [""]):
        if linea.startswith("## "):
            # Título principal (más grande y en negrita)
            partes.append(f"\\pard\\b\\fs48 {escapar_rtf(linea[3:])}\\b0\\fs24\\sa200\\par\n")
        elif linea.startswith("# "):
            # Subtítulo (un poco más grande y en negrita)
            partes.append(f"\\pard\\b\\fs32 {escapar_rtf(linea[2:])}\\b0\\fs24\\sb200\\sa100\\par\n")
        elif linea.strip() == "":
            # Línea vacía (espacio entre secciones)
            partes.append("\\pard\\par\n")
        else:
            # Texto normal
            partes.append(f"\\pard {escapar_rtf(linea)}\\par\n")

    partes.append("}")

    with open(ruta, "wb") as archivo:
        archivo.write("".join(partes).encode('utf-8'))

def exportar_curso_pdf(id_curso):
    # Consultar datos del curso
    cursor.execute("""
        SELECT docente_nombres, docente_apellido, docente_especialidad,
               tipo_documento, numero_documento, nacionalidad_docente,
               domicilio_docente, calle_numero_docente,
               especialidad, dias, horarios, duracion,
               establecimiento, fecha_de_iniciacion,
               lugar_en_el_que_se_dicta, localidad
        FROM cursos WHERE id = ?
    """, (id_curso,))
    curso = cursor.fetchone()
    
    if not curso:
        messagebox.showinfo("Sin resultados", "No se encontró ese curso.")
        return
    
    # Construir texto
    docente_completo = f"{curso[0] or ''} {curso[1] or ''}".strip()
    lineas = [
        f"## Curso: {curso[8] or 'Sin nombre'}",
        f"ID del curso: {id_curso}",
        "",
        "# DATOS DEL DOCENTE",
        f"Nombre: {curso[0] or '-'}",
        f"Apellido: {curso[1] or '-'}",
        f"Especialidad: {curso[2] or '-'}",
        f"Tipo de documento: {curso[3] or '-'}",
        f"Número de documento: {curso[4] or '-'}",
        f"Nacionalidad: {curso[5] or '-'}",
        f"Domicilio: {curso[6] or '-'}",
        f"Calle y número: {curso[7] or '-'}",
        "",
        "# INFORMACIÓN DEL CURSO",
        f"Días de cursada: {curso[9] or '-'}",
        f"Horarios: {curso[10] or '-'}",
        f"Duración: {curso[11] or '-'}",
        f"Establecimiento: {curso[12] or '-'}",
        f"Fecha de iniciación: {curso[13] or '-'}",
        f"Lugar en el que se dicta: {curso[14] or '-'}",
        f"Localidad: {curso[15] or '-'}"
    ]
    texto = "\n".join(lineas)
    
    # Guardar PDF
    ruta = filedialog.asksaveasfilename(
        title="Guardar curso como PDF",
        defaultextension=".pdf",
        initialfile=f"curso_{id_curso}.pdf",
        filetypes=[("PDF", "*.pdf")]
    )
    if not ruta:
        return
    
    try:
        crear_pdf_de_texto_cursos(ruta, texto)  # Sin foto
        messagebox.showinfo("OK", f"Curso guardado en:\n{ruta}")
    except Exception:
        traceback.print_exc()
        messagebox.showerror("Error", "No se pudo crear el PDF.")


